{
  "status": "SUPPORTED",
  "task_summary": "Set up refreshment stations and remote for two viewers.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_setting",
        "entity_kind": "OBJECT",
        "function": "A collection of items for consumption including a cup and plate.",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["cup", "plate", "beverage"],
        "required_properties": ["drinkable_container", "eating_surface"]
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "Device used to operate the television.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["remote", "control_panel"],
        "required_properties": ["button_interface"]
      },
      {
        "id": "surface",
        "entity_kind": "REGION",
        "function": "Flat area used to hold items.",
        "required_count": 2,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "desk", "shelf"],
        "required_properties": ["flat_top", "stable"]
      },
      {
        "id": "seating_location",
        "entity_kind": "REGION",
        "function": "Area where the two people sit.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["chair_group", "floor_area"],
        "required_properties": ["furnished", "in_front_of_tv"]
      },
      {
        "id": "television",
        "entity_kind": "FIXED_TARGET",
        "function": "Screen providing visual content.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["tv", "screen"],
        "required_properties": ["display"]
      }
    ],
    "functional_relations": [
      {
        "id": "near_viewer",
        "relation": "near",
        "participant_roles": [
          "refreshment_setting",
          "seating_location"
        ]
      ,
        "required": true
      }
    , {
        "id": "accessible_to_viewer",
        "relation": "accessible_from",
        "participant_roles": [
          "entertainment_control",
          "seating_location"
        ]
      ,
        "required": true
      }
    ]
  ,
    "operation_pairings": [
      {
        "id": "place_refreshments",
        "operation": "place_on",
        "participant_roles": [
          "refreshment_setting",
          "surface"
        ]
      ,
        "operation_count": 2
      }
    , {
        "id": "place_remote",
        "operation": "place_on",
        "participant_roles": [
          "entertainment_control",
          "surface"
        ]
      ,
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "refreshment_setting": [
        {
          "label": "desk_setup",
          "visual_description": "Two red cups and a white plate on the large wooden desk in the foreground."
        }
      , {
          "label": "side_table_item",
          "visual_description": "One red cup on the small side table to the left of the left chair."
        }
      ]
    , "entertainment_control": [
        {
          "label": "desk_remote",
          "visual_description": "Black rectangular remote on the large wooden desk."
        }
      ]
    , "surface": [
        {
          "label": "large_desk",
          "visual_description": "Large wooden desk in the foreground with drawers."
        }
      , {
          "label": "coffee_table",
          "visual_description": "Low rectangular table in the center with a light top."
        }
      , {
          "label": "side_tables",
          "visual_description": "Two small wooden tables flanking the chairs."
        }
      ]
    , "seating_location": [
        {
          "label": "carpeted_floor",
          "visual_description": "Light colored carpeted area between the chairs and the TV."
        }
      ]
    , "television": [
        {
          "label": "wall_mounted_tv",
          "visual_description": "Black flat screen mounted on the back wall."
        }
      ]
    }
  ,
    "inspectable_regions": [
      {
        "id": "desk_storage",
        "label": "Large wooden desk storage",
        "visual_description": "Drawers and lower shelves under the main desk surface visible in views 1 and 2.",
        "reason": "Could contain additional cups, plates, or drinks needed for the second refreshment setting."
      }
    , {
        "id": "side_table_storage",
        "label": "Side table storage",
        "visual_description": "Shelves under the small side tables.",
        "reason": "Could hold spare refreshment items."
      }
    ]
  ,
    "inspection_order": [
      "desk_storage",
      "side_table_storage",
      "wall_mounted_tv"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
